                .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
                .count();
        if (createdToday >= DAILY_LIMIT) {
            throw new OwnerDailyCreateLimitException(
                    "The daily limit of " + DAILY_LIMIT + " owner registrations has been reached");
        }
    }
}

